const params  = $('Webhook Trigger').first().json.params;
const body    = $('Webhook Trigger').first().json.body;
const rawBody = $('Webhook Trigger').first().json.rawBody;

const restaurantId        = params.restaurant_id;
const whatsappNumber      = body.message?.from;
const messageText         = body.message?.text?.body ?? '';
const kapsoConversationId = body.conversation?.id;
const phoneNumberId       = body.conversation?.phone_number_id;

// Skip non-text messages (images, audio, stickers, etc.)
if (!messageText.trim()) {
  return [{ json: { skip: true } }];
}

// Validate restaurant_id is a UUID
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!UUID_RE.test(restaurantId)) {
  throw new Error(`Invalid restaurant_id in URL: ${restaurantId}`);
}

if (!whatsappNumber) {
  throw new Error('Missing body.message.from — cannot identify sender');
}

return [{ json: {
  restaurantId,
  whatsappNumber,
  messageText,
  kapsoConversationId,
  phoneNumberId,
  rawBody,
} }];

const crypto  = require('crypto');

const restaurant = $('Fetch Restaurant').first().json;

// Handle array response from Supabase REST API
const restaurantRow = Array.isArray(restaurant) ? restaurant[0] : restaurant;

if (!restaurantRow?.id) {
  throw new Error('Restaurant not found for id: ' + $('Extract and Validate').first().json.restaurantId);
}

const secret  = restaurantRow.kapso_webhook_secret ?? '';
const rawBody = $('Extract and Validate').first().json.rawBody;
const header  = $('Webhook Trigger').first().json.headers['x-webhook-signature'] ?? '';

const expected = crypto
  .createHmac('sha256', secret)
  .update(rawBody, 'utf8')
  .digest('hex');

if (secret && header !== expected) {
  throw new Error('Webhook signature mismatch — request rejected');
}

// Expose restaurant data for downstream nodes
return [{ json: {
  restaurantId:   restaurantRow.id,
  restaurantName: restaurantRow.name,
  timezone:       restaurantRow.timezone,
  verified:       true,
} }];

const timezone = $('Verify Signature').first().json.timezone;
const items    = $('Fetch Active Menu (SQL)').all().map(i => i.json);

// Resolve current time in the restaurant's timezone
const now = new Date();
const fmt = new Intl.DateTimeFormat('en-US', {
  timeZone: timezone,
  weekday: 'short',
  hour:    '2-digit',
  minute:  '2-digit',
  hour12:  false,
});

const parts     = Object.fromEntries(fmt.formatToParts(now).map(p => [p.type, p.value]));
const DOW_MAP   = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
const dayOfWeek = DOW_MAP[parts.weekday];
const localTime = `${parts.hour.padStart(2, '0')}:${parts.minute}`;

const available = items.filter(item => {
  const schedules = typeof item.schedules === 'string'
    ? JSON.parse(item.schedules)
    : (item.schedules ?? []);

  if (schedules.length === 0) return true; // no schedule = always available

  return schedules.some(s => {
    const dayOk  = s.day_of_week.length === 0 || s.day_of_week.includes(dayOfWeek);
    const timeOk = localTime >= s.time_start && localTime <= s.time_end;
    return dayOk && timeOk;
  });
});

const dateStr = now.toLocaleDateString('en-US', {
  timeZone: timezone,
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
});

return [{ json: { items: available, localTime, weekdayName: parts.weekday, timezone, dateStr } }];

// Supabase REST returns an array; empty = no conversation in the 24h window
const response    = $('Find Conversation').first().json;
const foundConvs  = Array.isArray(response) ? response : [];
const existing    = foundConvs[0];

const restaurantId   = $('Extract and Validate').first().json.restaurantId;
const whatsappNumber = $('Extract and Validate').first().json.whatsappNumber;
const supabaseUrl    = $env.SUPABASE_URL;
const supabaseKey    = $env.SUPABASE_SERVICE_ROLE_KEY;
const now            = new Date().toISOString();

const headers = {
  'apikey':        supabaseKey,
  'Authorization': `Bearer ${supabaseKey}`,
  'Content-Type':  'application/json',
  'Prefer':        'return=representation',
};

let conversationId;

if (existing?.id) {
  // Update last_message_at on existing conversation
  const result = await this.helpers.httpRequest({
    method:  'PATCH',
    url:     `${supabaseUrl}/rest/v1/conversations?id=eq.${existing.id}`,
    headers,
    body:    JSON.stringify({ last_message_at: now }),
    json:    false,
  });
  const rows = JSON.parse(result);
  conversationId = rows[0].id;
} else {
  // Create a new conversation
  const result = await this.helpers.httpRequest({
    method:  'POST',
    url:     `${supabaseUrl}/rest/v1/conversations`,
    headers,
    body:    JSON.stringify({
      restaurant_id:    restaurantId,
      whatsapp_number:  whatsappNumber,
      started_at:       now,
      last_message_at:  now,
    }),
    json: false,
  });
  const rows = JSON.parse(result);
  conversationId = rows[0].id;
}

return [{ json: { conversationId } }];

const restaurantName = $('Verify Signature').first().json.restaurantName;
const filtered       = $('Filter by Day and Time').first().json;
const userMsg        = $('Extract and Validate').first().json.messageText;

// History from Supabase is an array in $json (newest first) — reverse to chronological
const rawHistory = $('Fetch History').first().json;
const historyArr = (Array.isArray(rawHistory) ? rawHistory : []).reverse();
// Exclude the user message we just inserted (last item is the one we saved)
const history = historyArr.slice(0, -1);

// Group available items by category for the menu JSON
const byCategory = {};
for (const item of filtered.items) {
  if (!byCategory[item.category]) byCategory[item.category] = [];
  byCategory[item.category].push({
    name:        item.name,
    description: item.description ?? null,
    price:       item.price ?? null,
    chef_pick:   item.chef_recommendation,
    chef_note:   item.chef_note ?? null,
  });
}

const menuJson = JSON.stringify(byCategory, null, 2);

const systemPrompt =
`You are a friendly restaurant assistant for ${restaurantName}.
Your only job is to help diners explore the menu and make recommendations.
You do NOT take orders.
Always respond in the same language the diner is using.
Supported languages: English, Spanish, German, French, Italian.

Today is ${filtered.dateStr}. Current time: ${filtered.localTime} (${filtered.timezone}).

Available menu (JSON — grouped by category):
${menuJson}

Items marked chef_pick: true are chef recommendations — highlight them with ⭐.
Only recommend items listed above; unavailable items have already been filtered out.
Keep responses warm, concise, and helpful.`;

// Build messages array for the Anthropic API
const messages = [
  ...history.map(m => ({ role: m.role, content: m.content })),
  { role: 'user', content: userMsg },
];

return [{ json: { systemPrompt, messages } }];

